  _globals['_INTERNALTRANSFERSERVICE'].methods_by_name['CreateInternalTransfer']._loaded_options = None
  _globals['_INTERNALTRANSFERSERVICE'].methods_by_name['CreateInternalTransfer']._serialized_options = b'\272G\317\003\n\022Internal Transfers\022\030Create Internal Transfer\032\236\003Create or return one authenticated Trading to Trading internal transfer. Root-owner same-owner transfers and root-owner transfers to explicitly whitelisted destinations accept an MFA-elevated session (MFA completed in the last 30 minutes); delegated and other interactive transfers require fresh step-up. Without them the transfer is refused HTTP 403 with code AUTH_MFA_ELEVATION_REQUIRED or AUTH_STEP_UP_REQUIRED.\230\265\030\003\242\265\030\002\001\002\202\323\344\223\002#\"\036/v1/trading/internal-transfers:\001*'
