  _globals['_INTERNALTRANSFERSERVICE'].methods_by_name['BatchCreateInternalTransfers']._serialized_options = b'\272G\252\003\n\022Internal Transfers\022\037Batch Create Internal Transfers\032\362\002Move up to 500 Trading to Trading transfers together, authorized by one MFA check: every leg is credited, or none moves. A batch debits at most 50 distinct source account and asset pairs from at most 10 source accounts. A batch without the MFA-elevated session or fresh step-up it needs is refused HTTP 403 with code AUTH_MFA_ELEVATION_REQUIRED or AUTH_STEP_UP_REQUIRED.\230\265\030\003\242\265\030\002\001\002\202\323\344\223\002)\"$/v1/trading/internal-transfers/batch:\001*'
